import pathlib,subprocess,os,json,hashlib
from offline_receipts import publish_stage, finish
repo=pathlib.Path(__file__).resolve().parent.parent
p=repo/'build/offline';p.mkdir(parents=True,exist_ok=True)
env={k:v for k,v in os.environ.items() if not k.startswith(('CLOUDSIGMA','TF_'))}
env.update(GOPROXY='off',GOSUMDB='off',CGO_ENABLED='0')
groups={'internal/cloudsigmaapi':['TestSnapshotCallerContext','TestServerCreateBlockedRead','TestServerCreate','TestServerCreateBoundaries','TestDriveClone','TestDriveCallerContext','TestIndependentPOST','TestDriveCreateR1Transport','TestDriveCreate','TestServerCallerContext','TestServerPower','TestServerPowerBoundaries','TestServerDelete','TestServerDeleteBoundaries','TestServerDeleteFailures','TestDriveDelete','TestDriveDeleteBoundaries','TestDriveDeleteFailures','TestServer','TestServerBoundaries','TestKeypairUpdate','TestKeypairUpdateBoundaries','TestKeypairUpdateFailures','TestKeypairDelete','TestKeypairDeleteBoundaries','TestKeypairDeleteFailures','TestSnapshotDelete','TestSnapshotDeleteBoundaries','TestSnapshotHeldMutationOracle','TestKeypairs','TestKeypairHTTP','TestKeypairInvalidID','TestKeypairBoundaries','TestKeypairPubkeyCoexistence','TestPubkeys','TestPubkeyHTTP','TestPubkeyInvalidID','TestPubkeyBoundaries','TestSnapshotBoundaries','TestSnapshots','TestSnapshotHTTP','TestSnapshotInvalidID','TestTags','TestTagsHTTP','TestTagListBoundaries','TestVLANHTTP','TestVLANs','TestVLANListBoundaries','TestVLANSingleBoundaries','TestIPHTTP','TestIPs','TestIPListBoundaries','TestIPSingleBoundaries','TestDriveHTTP','TestDrives','TestDriveListBoundaries','TestDriveSingleBoundaries','TestLibraryHTTP','TestLibraryDrives','TestLibraryListBoundaries','TestLibrarySingleBoundaries','TestSubscriptions','TestSubscriptionsBoundaries','TestLicenses','TestLicensesBoundaries','TestLocations','TestClient','TestClientRedirect','TestProfile','TestReviewReadError','TestReviewEarlierDeadline','TestReviewCancellationDuringRead','TestReviewDeadlineDuringRead'],'cloudsigma':['TestNative27Callback','TestNative26Dispatch','TestNative26AckCancel','TestNative26RichSuccess','TestNative26AttachmentFaults','TestNative25CloneCallback','TestOfflineServerDeletePreflight','TestNativeDriveWaiter','TestIndependentCredentialPaths','TestNativeCreateR1Callback','TestOfflineNativeDriveCreate','TestOfflineNativeServerPower','TestOfflineNativeServerPowerCredentials','TestOfflineLegacyNativeServerDelete','TestOfflineLegacyNativeServerDeleteCancellation','TestOfflineLegacyNativeServerDeleteCredentialParity','TestOfflineLegacyNativeServerDeletePreparation','TestOfflineDriveDeleteMetadataCoexistence','TestOfflineLegacyNativeDriveDelete','TestOfflineLegacyNativeDriveDeleteCancellation','TestOfflineLegacyNativeDriveDeleteCredentialParity','TestOfflineLegacyNativeDriveDeleteMounted','TestOfflineServerMetadataAtomic','TestOfflineLegacyNativeServerRead','TestOfflineLegacyNativeServerCancellation','TestOfflineLegacyNativeServerCredentialParity','TestOfflineLegacyNativeCredentialParity','TestOfflineLegacyNativeDriveRead','TestOfflineLegacyNativeDriveCancellation','TestOfflineLegacyClientSeam','TestOfflineLegacyCallbackExtraction','TestProvider','TestProvider_impl','TestOfflineRefresh','TestOfflineCloneEmptyGuard','TestOfflinePrivacyFixed','TestResourceCloudSigmaServer_findIPv4Address','TestStructureDrive_expandTags','TestStructureDrive_flattenTags','TestStructureServer_expandEnclavePageCaches','TestStructureServer_flattenEnclavePageCaches'],'internal/provider':['TestNative28Matrix','TestNative28SnapshotLifecycle','TestOfflineNativeSSHKeyUpdate','TestOfflineNativeSSHKeyUpdateInvalid','TestOfflineNativeSSHKeyDelete','TestOfflineNativeSSHKeyDeleteInvalid','TestOfflineNativeSnapshotDelete','TestOfflineNativeSnapshotDeleteInvalid','TestOfflineNativeSSHKey','TestOfflineNativeSSHKeyStateBoundaries','TestOfflineNativeSnapshot','TestOfflineNativeTagConfigure','TestOfflineTagCancel','TestOfflineNativeTag','TestOfflineVLANCancel','TestOfflineNativeVLAN','TestOfflineIPCancel','TestOfflineNativeIP','TestOfflineDriveCancel','TestOfflineNativeDrive','TestOfflineLibraryCancel','TestOfflineNativeLibraryDrive','TestOfflineNativeSubscription','TestOfflineNativeLicense','TestOfflineNativeLocation','TestOfflineNativeAuthMatrix','TestOfflineNativeConfigure','TestOfflineNativeState','TestOfflineImportProtocol','TestOfflineNetworkProjectedState','TestOfflineDatasourceCoverage','TestOfflineConfiguredReadonly','TestOfflineConfigurePrivacy','TestOfflineDatasourceReads','TestOfflineRegisteredSchemas','TestOfflineSnapshotPrivacy','TestOfflineDestroyStatus','TestOfflineSnapshotDependencyCleanup'],'readonly':['TestFence']}
records=[]
(p/'execution.json').write_text('[]')
for pkg,names in groups.items():
 tag=pkg.replace('/','-');guard=p/(tag+'_guard_test.go');guard.write_text((repo/'scripts/guard.template').read_text().replace('PACKAGE',pkg.split('/')[-1]));overlay=p/(tag+'-overlay.json');overlay.write_text(json.dumps({'Replace':{str(repo/pkg/'zz_isolation_guard_test.go'):str(guard)}}));binary=p/(tag+'.test')
 slow=[n for n in names if n.startswith(('TestNative26', 'TestNative28'))];names=[n for n in names if n not in slow]
 commands=[['go','test','-vet=off','-overlay',str(overlay),'-c','-o',str(binary),'./'+pkg],[str(binary),'-test.run','^TestIsolationCanaries$','-test.v=test2json'],[str(binary),'-test.run','^('+'|'.join(names)+')$','-test.v=test2json','-test.count=1']]
 commands += [[str(binary),'-test.run','^'+n+'$','-test.v=test2json','-test.timeout','590s'] for n in slow]
 for stage,cmd in zip(['build','canary','suite']+slow,commands):
  if stage != 'build': cmd=['go','tool','test2json','-p',pkg]+cmd
  try:
   r=subprocess.run(cmd,cwd=repo,env=env,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,timeout=600)
  except subprocess.TimeoutExpired as error:
   r=subprocess.CompletedProcess(cmd,124,error.stdout or b'')
  except OSError as error:
   r=subprocess.CompletedProcess(cmd,127,str(error).encode())
  (p/(tag+'-'+stage+'.log')).write_bytes(r.stdout);records.append({'package':pkg,'stage':stage,'argv':cmd,'exit':r.returncode});(p/'execution.json').write_text(json.dumps(records,indent=2));
  publish_stage(p,records[-1])
  if stage == 'build' and not r.returncode:
   inventory=subprocess.run([str(binary),'-test.list','.*'],cwd=repo,env=env,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,timeout=600)
   actual=inventory.stdout.decode().splitlines()
   if inventory.returncode or not set(names+slow+['TestIsolationCanaries']).issubset(actual): raise SystemExit('inventory refused')
   (p/(tag+'-inventory.json')).write_text(json.dumps(actual))
  if r.returncode:raise SystemExit('failed '+tag+' '+stage)
(p/'binaries.json').write_text(json.dumps({f.name:hashlib.sha256(f.read_bytes()).hexdigest() for f in p.glob('*.test')},indent=2))

finish(p, records)
